package com.glitched.overheadmute;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class OverheadMutePluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(OverheadMutePlugin.class);
		RuneLite.main(args);
	}
}

package com.glitched.overheadmute;

import net.runelite.client.config.*;

@ConfigGroup("overheadmute")
public interface OverheadMuteConfig extends Config
{
    @ConfigItem(
            keyName = "hideLocalOverhead",
            name = "Hide local overhead",
            description = "Hide overhead text above your own player."
    )
    default boolean hideLocalOverhead()
    {
        return true;
    }

    @ConfigItem(
            keyName = "hideOtherOverhead",
            name = "Hide other overhead",
            description = "Hide overhead text above other players (not your own)."
    )
    default boolean hideOtherOverhead()
    {
        return false;
    }

    @ConfigItem(
            keyName = "useRegex",
            name = "Filter by regex",
            description = "Hide overhead/chat text matching regex for you and other players."
    )
    default boolean useRegex()
    {
        return true;
    }

    @ConfigItem(
            keyName = "regex",
            name = "Regex",
            description = "One regex per line."
    )
    default String regex()
    {
        return "";
    }
}

package com.glitched.overheadmute;

import com.google.inject.Provides;
import javax.inject.Inject;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;

import net.runelite.api.Actor;
import net.runelite.api.ChatLineBuffer;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.MessageNode;
import net.runelite.api.Player;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.OverheadTextChanged;
import net.runelite.client.util.Text;

import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@PluginDescriptor(
        name = "Overhead Mute",
        description = "Hide overhead text and remove matching chat lines"
)
public class OverheadMutePlugin extends Plugin
{
    @Inject
    private Client client;

    @Inject
    private OverheadMuteConfig config;

    private List<Pattern> patterns = Collections.emptyList();
    private String lastRegexList;

    @Provides
    OverheadMuteConfig provideConfig(ConfigManager manager)
    {
        return manager.getConfig(OverheadMuteConfig.class);
    }

    private List<Pattern> getPatterns()
    {
        final String regexList = config.regex();
        if (regexList == null || regexList.trim().isEmpty())
        {
            lastRegexList = regexList;
            patterns = Collections.emptyList();
            return patterns;
        }

        // Recompile if changed
        if (lastRegexList == null || !lastRegexList.equals(regexList))
        {
            patterns = compilePatterns(regexList);
            lastRegexList = regexList;
        }

        return patterns;
    }

    private boolean matches(String text)
    {
        if (!config.useRegex() || text == null)
        {
            return false;
        }

        for (Pattern p : getPatterns())
        {
            if (p.matcher(text).find())
            {
                return true;
            }
        }

        return false;
    }

    private static List<Pattern> compilePatterns(String regexList)
    {
        List<Pattern> compiled = new ArrayList<>();
        for (String line : regexList.split("\\R"))
        {
            String trimmed = line.trim();
            if (trimmed.isEmpty())
            {
                continue;
            }

            Pattern pattern = compilePattern(trimmed);
            if (pattern != null)
            {
                compiled.add(pattern);
            }
        }

        return compiled;
    }

    private static Pattern compilePattern(String pattern)
    {
        try
        {
            return Pattern.compile(pattern, Pattern.CASE_INSENSITIVE);
        }
        catch (PatternSyntaxException ex)
        {
            return null;
        }
    }

    @Subscribe
    public void onOverheadTextChanged(OverheadTextChanged e)
    {
        final Actor actor = e.getActor();
        final String text = e.getOverheadText();

        if (actor == null || text == null || text.isEmpty())
        {
            return;
        }

        final Player local = client.getLocalPlayer();

        if (config.hideOtherOverhead())
        {
            if (local == null || actor != local)
            {
                actor.setOverheadText("");
                return;
            }
        }

        if (config.hideLocalOverhead() && local != null && actor == local)
        {
            actor.setOverheadText("");
            return;
        }

        if (matches(text))
        {
            actor.setOverheadText("");
        }
    }

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        final MessageNode node = event.getMessageNode();
        if (node == null)
        {
            return;
        }

        final String msg = Text.removeTags(event.getMessage());
        if (msg == null || msg.isEmpty())
        {
            return;
        }

        if (!matches(msg))
        {
            return;
        }

        // getChatLineMap is keyed by int (message type id), not ChatMessageType itself
        final ChatMessageType type = event.getType();
        final int typeId = type.getType();

        final ChatLineBuffer buffer = client.getChatLineMap().get(typeId);
        if (buffer != null)
        {
            buffer.removeMessageNode(node);
        }
    }
}
